"use strict";(self.webpackChunkmira_docs_pl=self.webpackChunkmira_docs_pl||[]).push([["6472"],{5349(a){a.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"wersja-1.7.3","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.7.3","source":"@site/blog/2026-09-06-wersja-1.7.3.mdx","title":"TOU Mira 1.7.3","description":"Link do pobrania --\x3e Town Of Us: Mira v1.7.3","date":"2026-09-06T00:00:00.000Z","tags":[{"inline":false,"label":"Aktualizacja","permalink":"/Toum-Dokumentacja/blog/tags/aktualizacja"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.7.3","title":"TOU Mira 1.7.3","tags":["aktualizacja"]},"unlisted":false,"nextItem":{"title":"TOU Mira 1.7.2","permalink":"/Toum-Dokumentacja/blog/wersja-1.7.2"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.7.3](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.3)\\r\\n\\r\\nNa wersj\u0119 Among Us v18\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Ghostwalkerzy (Spectre/Haunter) mog\u0105 si\u0119 pojawia\u0107 w ventach, zamiast na ventach (Ustawienie)\\r\\n- Prosecutor mo\u017Ce by\u0107 teraz jedyn\u0105 osob\u0105 wyrzucon\u0105 po b\u0142\u0119dnym Prosecute (Ustawienie)\\r\\n- Przetasowanie kart w Draftcie daje teraz dodatkowy czas\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Sheriff i Altruista maj\u0105 naprawione wyt\u0142umaczenie w role tabie\\r\\n- Lustro Mirrorcastera nie zostaje permanentnie je\u015Bli Mirrorcaster zosta\u0142 przekonwertowany\\r\\n### Bug Fixy Impostor\xf3w:\\r\\n- U\u017Cycia Morph nie mog\u0105 zej\u015B\u0107 poni\u017Cej 0\\r\\n### Bug Fixy Neutrali:\\r\\n- Survivor nie zabiera wygranej Impostorom\\r\\n- Zaraza od Plaguebearera nie mo\u017Ce by\u0107 ju\u017C na jednym graczu 2 razy\\r\\n- Killcooldown Werewolfa podczas Rampage nie jest zmieniany przez efekty cooldown\xf3w (np. Diseased/Overclock)\\r\\n### Bug Fixy Draftu:\\r\\n- Role z celami (Exe/Fairy) maj\u0105 swoje cele przypisywane poprawnie\\r\\n- Multi wyb\xf3r nie zabiera ju\u017C opcji innym gracz\u0105\\r\\n### Inne Bug Fixy:\\r\\n- Naprawiono z\u0142y kod Amonga kt\xf3ry powodowa\u0142 wyrzucanie graczy gdy kto\u015B umar\u0142 podczas spotkania\\r\\n- Naprawiono rol\u0119 z customowych tryb\xf3w gry pojawi\u0105ce si\u0119 w normalnych menu\\r\\n- Naprawiono brakuj\u0105ce powody \u015Bmierci nad nickami\\r\\n- Naprawiono tekst Assailant modyfikator\xf3w\\r\\n- Naprawiono killcooldown Impostor\xf3w w niekt\xf3rych sytuacjach"},{"id":"wersja-1.7.2","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.7.2","source":"@site/blog/2026-09-05-wersja-1.7.2.mdx","title":"TOU Mira 1.7.2","description":"Link do pobrania --\x3e Town Of Us: Mira v1.7.2","date":"2026-09-05T00:00:00.000Z","tags":[{"inline":false,"label":"Aktualizacja","permalink":"/Toum-Dokumentacja/blog/tags/aktualizacja"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.7.2","title":"TOU Mira 1.7.2","tags":["aktualizacja"]},"unlisted":false,"prevItem":{"title":"TOU Mira 1.7.3","permalink":"/Toum-Dokumentacja/blog/wersja-1.7.3"},"nextItem":{"title":"TOU Mira 1.6.3 Beta 2","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta2"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.7.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.7.2)\\r\\n\\r\\nNa wersj\u0119 Among Us v18\\r\\n\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Prosecutor, Politician, Mayor i Hypnotist korzystaj\u0105 teraz z nowego systemu umiej\u0119tno\u015Bci na spotkaniu\\r\\n- Vampire liczy si\u0119 teraz jako 2 Neutralnych Zab\xf3jc\xf3w podczas Draftu\\r\\n- Janitor mo\u017Ce mie\u0107 teraz rozdzielone Cooldowny sprz\u0105tania i zabijania gdy jest ostatnim Impostorem (Ustawienie)\\r\\n- Mayor i Deputy (je\u015Bli ujawniony) po przekonwertowaniu (Vampire/Traitor) dalej b\u0119d\u0105 publicznie widoczni jako swoja oryginalna rola\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Martwi zab\xf3jcy nie dostaj\u0105 ju\u017C strza\u0142ki w stron\u0119 Hauntera\\r\\n- Deputy nie mo\u017Ce by\u0107 ju\u017C zgadni\u0119ty po ujawnieniu\\r\\n- Tekst z u\u017Cyciami Prosecute wy\u015Bwietla si\u0119 teraz poprawnie\\r\\n- Zamienieni gracze przez Swappera poprawnie te\u017C zmieniaj\u0105 tekst dla daltonist\xf3w\\r\\n### Bug Fixy Neutrali:\\r\\n- Je\u015Bli Doomsayer kontynuuje gr\u0119 i powinien wygra\u0107 gdy zgadnie wszystkich, gra nie sko\u0144czy si\u0119 ju\u017C wygran\u0105 Crewmate\'\xf3w\\r\\n- Informacje z Observe s\u0105 teraz poprawnie wy\u015Bwietlane\\r\\n- Transformacja Plaguebearera w Pestilence jest wykonywana poprawnie w skrajnych przypadkach\\r\\n### Bug Fixy Modyfikator\xf3w:\\r\\n- Gdy gracz z modyfikatorem Deadly Quota zabija ostani\u0105 osob\u0119 w grze, ten kill poprawnie b\u0119dzie si\u0119 liczy\u0107 do wymaganych\\r\\n- Overclocker nie daje ju\u017C Impostorom 0 sekund Cooldownu\\r\\n- Tiebreaker nie kontynuuje gry gdy jest martwy\\r\\n- Noisemaker nie zostaje widoczny gdy cia\u0142o zosta\u0142o wyczyszczone\\r\\n- Bait nie zostaje zg\u0142oszony je\u015Bli cia\u0142o zosta\u0142o wyczyszczone w czasie\\r\\n### Draft Mode Bug Fixy:\\r\\n- Ilo\u015B\u0107 kart nie jest ju\u017C decydowana przez ilo\u015B\u0107 graczy w lobby\\r\\n- Przetasowanie nie zmniejsza ilo\u015Bci kart\\r\\n### Inne Bug Fixy:\\r\\n- Nicki b\u0105d\u017A kosmetyki od Ambushera, Morphlinga i Swoopera nie przenosz\u0105 si\u0119 ju\u017C na spotkania\\r\\n- Dodano wsparcie dla najnowszej wersji Level Imposter\\r\\n- Naprawiono zepsute Patche Submergeda\\r\\n- Neutralni Zab\xf3jcy nie maj\u0105 ju\u017C priorytetu przy remisach. Gra poprawnie ko\u0144czy si\u0119 jako Remis"},{"id":"wersja-1.6.3beta2","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta2","source":"@site/blog/2026-06-29-wersja-1.6.3beta2.mdx","title":"TOU Mira 1.6.3 Beta 2","description":"Link do pobrania --\x3e Town Of Us: Mira v1.6.3 Beta 2","date":"2026-06-29T00:00:00.000Z","tags":[{"inline":false,"label":"Beta","permalink":"/Toum-Dokumentacja/blog/tags/beta"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.6.3beta2","title":"TOU Mira 1.6.3 Beta 2","tags":["beta"]},"unlisted":false,"prevItem":{"title":"TOU Mira 1.7.2","permalink":"/Toum-Dokumentacja/blog/wersja-1.7.2"},"nextItem":{"title":"TOU Mira 1.6.3 Beta 1","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta1"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.6.3 Beta 2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.3-beta2)\\r\\n\\r\\n**WA\u017BNE**\\\\\\r\\nNale\u017Cy u\u017Cy\u0107 wersji Among Us v17.3\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Nowe Ustawienie: Swooper mo\u017Ce by\u0107 nietrackowalny podczas Swoopa\\r\\n- Nowe Ustawienie: Niekt\xf3ry neutralne role maj\u0105 teraz ustawienie aby by\u0142o wida\u0107, \u017Ce opu\u015Bci\u0142y gr\u0119 wygranym\\r\\n- Nowe Ustawienie: Soul Collector mo\u017Ce mie\u0107 zablokowane zabijanie w pierwszej rundzie\\r\\n- Gracze z blackmailem nie b\u0119d\u0105 auto skipowa\u0107 odrazu po ko\u0144cu \\"Discussion Phase\\" tylko w losowym momencie w podczas meetingu\\r\\n- Wiki w grze nie \u015Bcina si\u0119 po ponownym otworzeniu wyszukiwarki\\r\\n- Umiej\u0119tno\u015Bci kt\xf3re s\u0105 wy\u0142\u0105czone przez pierwsz\u0105 rund\u0119 s\u0105 teraz oznaczone\\r\\n- Par\u0119 r\xf3l dosta\u0142o dodatkowe efekty wizualne/audio\\r\\n- Modyfikatory maj\u0105 teraz przypisane czy mog\u0105 by\u0107 zgadni\u0119te w wiki\\r\\n- Medic widzi plakietki Lighter/Darker na wszystkich graczach zamiast tylko tych \u017Cywych\\r\\n- Jailor ma specjaln\u0105 posta\u0107 na chatcie wi\u0119zienia\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Strza\u0142ki duszy Mediuma poprawnie wy\u015Bwietlaj\u0105 si\u0119 dla ka\u017Cdego a nie tylko hosta\\r\\n- \\"Medium can Identify\\" ustawienie poprawnie ukrywa duchy\\r\\n- Strza\u0142ki Mystica nie pojawiaj\u0105 si\u0119 ju\u017C gdy Duration jest ustawione na 0s\\r\\n- Swapper i Prosecutor poprawnie wp\u0142ywaj\u0105 na to kogo mo\u017Ce zabi\u0107 Exe/Jester oraz zemst\u0119 Huntera\\r\\n### Bug Fixy Neutrali:\\r\\n- Powiadomienie o opuszczeniu gry przez Exe i Doomsayera pojawia si\u0119 poprawnie dla wszystkich\\r\\n- Hack Glitcha nie powstrzymuje ju\u017C zab\xf3jc\xf3w od zabiajania do ko\u0144ca gry\\r\\n- Gracze zabici przez Soul Collectora poprawnie dostaj\u0105 nick po kamufla\u017Cu\\r\\n### Bug Fixy Modyfikator\xf3w:\\r\\n- Crewpostor Vigilante nie mo\u017Ce ju\u017C zgadywa\u0107 Impostor\xf3w\\r\\n### Inne Bug Fixy:\\r\\n- Zmienianie zak\u0142adek wiki za szybko na v17.3 nie powodu ju\u017C crash\xf3\\r\\n- Neutral Wildcard nie duplikuje ju\u017C r\xf3l\\r\\n- Przedmioty kosmetyczne nie psuj\u0105 si\u0119 ju\u017C na v17.4"},{"id":"wersja-1.6.3beta1","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta1","source":"@site/blog/2026-06-20-wersja-1.6.3beta1.mdx","title":"TOU Mira 1.6.3 Beta 1","description":"Link do pobrania --\x3e Town Of Us: Mira v1.6.3 Beta 1","date":"2026-06-20T00:00:00.000Z","tags":[{"inline":false,"label":"Beta","permalink":"/Toum-Dokumentacja/blog/tags/beta"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.6.3beta1","title":"TOU Mira 1.6.3 Beta 1","tags":["beta"]},"unlisted":false,"prevItem":{"title":"TOU Mira 1.6.3 Beta 2","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta2"},"nextItem":{"title":"TOU Mira 1.6.3","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.6.3 Beta 1](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.3-beta1)\\r\\n\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Nowe Ustawienie: Swooper mo\u017Ce by\u0107 nietrackowalny podczas Swoopa\\r\\n- Nowe Ustawienie: Niekt\xf3ry neutralne role maj\u0105 teraz ustawienie aby by\u0142o wida\u0107, \u017Ce opu\u015Bci\u0142y gr\u0119 wygranym\\r\\n- Nowe Ustawienie: Soul Collector mo\u017Ce mie\u0107 zablokowane zabijanie w pierwszej rundzie\\r\\n- Umiej\u0119tno\u015Bci kt\xf3re s\u0105 wy\u0142\u0105czone przez pierwsz\u0105 rund\u0119 s\u0105 teraz oznaczone\\r\\n- Par\u0119 r\xf3l dosta\u0142o dodatkowe efekty wizualne/audio\\r\\n- Modyfikatory maj\u0105 teraz przypisane czy mog\u0105 by\u0107 zgadni\u0119te w wiki\\r\\n- Medic widzi plakietki Lighter/Darker na wszystkich graczach zamiast tylko tych \u017Cywych\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Strza\u0142ki duszy Mediuma poprawnie wy\u015Bwietlaj\u0105 si\u0119 dla ka\u017Cdego a nie tylko hosta\\r\\n- \\"Medium can Identify\\" ustawienie poprawnie ukrywa duchy\\r\\n### Bug Fixy Neutrali:\\r\\n- Powiadomienie o opuszczeniu gry przez Exe i Doomsayera pojawia si\u0119 poprawnie dla wszystkich\\r\\n- Hack Glitcha nie powstrzymuje ju\u017C zab\xf3jc\xf3w od zabiajania do ko\u0144ca gry\\r\\n### Inne Bug Fixy:\\r\\n- Zmienianie zak\u0142adek wiki za szybko na v17.3 nie powodu ju\u017C crash\xf3\\r\\n- Neutral Wildcard nie duplikuje ju\u017C r\xf3l"},{"id":"wersja-1.6.3","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3","source":"@site/blog/2026-06-13-wersja-1.6.3.mdx","title":"TOU Mira 1.6.3","description":"Link do pobrania --\x3e Town Of Us: Mira v1.6.3","date":"2026-06-13T00:00:00.000Z","tags":[{"inline":false,"label":"Aktualizacja","permalink":"/Toum-Dokumentacja/blog/tags/aktualizacja"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.6.3","title":"TOU Mira 1.6.3","tags":["aktualizacja"]},"unlisted":false,"prevItem":{"title":"TOU Mira 1.6.3 Beta 1","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3beta1"},"nextItem":{"title":"TOU Mira 1.6.2","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.2"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.6.3](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.3)\\r\\n\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Miner zawsze stawia venty z polusa i ma do nich przypisan\u0105 animacje\\r\\n- Sonar zamiast strza\u0142ek mo\u017Ce mie\u0107 czujniki bi\u0107 serc z Chowanego\\r\\n- Ujawnieni gracze przez Hauntera b\u0119d\u0105 widzieli sw\xf3j nick na bordowo\\r\\n- Glitch, Morphling i Swooper maj\u0105 lepsze ustawienia do ventowania\\r\\n- ToU Mira: Legacy jest teraz cz\u0119\u015Bci\u0105 g\u0142\xf3wnego moda\\r\\n- Po\u0142o\u017Cenie roli przy nicku jest teraz konfigurowalne\\r\\n- Po\u0142o\u017Cenie znaczka **Mod** jest teraz konfigurowalne\\r\\n- Dekoracja Skelda **TV Show** jest teraz mo\u017Cliwa do ustawienia za pomoc\u0105 Better Map Settings\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Officer traktuje Prosecutora jako poprawy kill (je\u015Bli ten u\u017Cy\u0142 Prosecute)\\r\\n- Monarch nie jest ju\u017C odporny na podstawowe interakcje gdy ma tarcz\u0119\\r\\n- Czas trwania Barriery Clerica nie jest przypisany do cooldownu\\r\\n- Warden nie resetuje ju\u017C cooldownu do 1 sekundy\\r\\n- Barykada Plumbera poprawnie powstrzymuje wszystkie role ventuj\u0105ce\\r\\n- Kamery Sentry nie s\u0105 ju\u017C ukryte pod pod\u0142og\u0105 w niekt\xf3rych miejscach\\r\\n### Bug Fixy Neutrali:\\r\\n- Maksymalna ilo\u015B\u0107 Douse dla Arsonisty nie jest ju\u017C wi\u0119ksza ni\u017C ustawiona\\r\\n- Executioner nie mo\u017Ce ju\u017C u\u017Cy\u0107 Tormentu je\u015Bli jego cel sta\u0142 si\u0119 z\u0142y\\r\\n### Bug Fixy Impostor\xf3w:\\r\\n- Shapeshifter poprawnie kopiuje wygl\u0105d tarczy\\r\\n- Parasite i Puppeteer podczas kontroli mog\u0105 poprawnie korzysta\u0107 z Drabin, Platformy i Tyrolki\\r\\n### Inne Bug Fixy:\\r\\n- Zak\u0142adka z petami poprawnie nazywa si\u0119 \\"Pets\\" zamiast \\"Hats\\"\\r\\n- Nie mo\u017Cna ju\u017C otworzy\u0107 Vitals\xf3w/Admina/Kamer je\u015Bli nie zosta\u0142o spe\u0142nione wymaganie task\xf3w\\r\\n- End Game Timer dzia\u0142a znowu poprawnie"},{"id":"wersja-1.6.2","metadata":{"permalink":"/Toum-Dokumentacja/blog/wersja-1.6.2","source":"@site/blog/2026-05-11-wersja-1.6.2.mdx","title":"TOU Mira 1.6.2","description":"Link do pobrania --\x3e Town Of Us: Mira v1.6.2","date":"2026-05-11T00:00:00.000Z","tags":[{"inline":false,"label":"Aktualizacja","permalink":"/Toum-Dokumentacja/blog/tags/aktualizacja"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"wersja-1.6.2","title":"TOU Mira 1.6.2","tags":["aktualizacja"]},"unlisted":false,"prevItem":{"title":"TOU Mira 1.6.3","permalink":"/Toum-Dokumentacja/blog/wersja-1.6.3"}},"content":"Link do pobrania --\x3e [Town Of Us: Mira v1.6.2](https://github.com/AU-Avengers/TOU-Mira/releases/tag/1.6.2)\\r\\n\\r\\n### Nowo\u015Bci i Zmiany\\r\\n- Monarch nie mo\u017Ce ju\u017C zmieni\u0107 wygl\u0105du swojej tarczy, w zamian tego b\u0119dzie zawsze dawa\u0142 szare migni\u0119cia (te same co rol\u0119 neutralne)\\r\\n- Seer nie mo\u017Ce ju\u017C por\xf3wnywa\u0107 ujawnionych graczy\\r\\n- Dodano mo\u017Cliwo\u015B\u0107 wy\u0142\u0105czenia specjalnych keybind\xf3w hosta\\r\\n- Tarcze Survivora, Fairy oraz pierwszej rundy b\u0119d\u0105 zawsze dawa\u0107 takie same, szare migni\u0119cia\\r\\n- 2 nowe customowe pety zosta\u0142y dodane\\r\\n- Nowa opcja gry \\"All Shields Flash Anonymously\\" pozwala ustawi\u0107, aby ka\u017Cda tarcza dawa\u0142a szare migni\u0119cia, zamiast w kolorze roli (np. Medic - Zielone migni\u0119cie)\\r\\n- Przyciski w prawym g\xf3rnym mog\u0105 by\u0107 teraz powi\u0119kszone / zmiejszone\\r\\n\\r\\n{/* truncate */}\\r\\n\\r\\n### Bug Fixy Crewmate\'\xf3w:\\r\\n- Pr\u0119dko\u015B\u0107 duszy mediuma nie zmienia si\u0119 podczas cofania czasu\\r\\n- Zab\xf3jcy poprawnie dostaj\u0105 strza\u0142ki do Hauntera gdy ten sko\u0144czy taski\\r\\n- Medic nie psuje si\u0119 ju\u017C gdy par\u0119 Medic\xf3w chroni t\u0105 sam\u0105 osob\u0119\\r\\n### Bug Fixy Neutrali:\\r\\n- Glitch nie resetuje ju\u017C cooldownu Mimica dla innych Glitch\xf3w\\r\\n### Bug Fixy Impostor\xf3w:\\r\\n- Efekt Venerera nie wy\u015Bwietla si\u0119 ju\u017C w modyfikatorach\\r\\n### Inne Bug Fixy:\\r\\n- Zmienianie skali UI podczas gry nie psuje ju\u017C UI w prawym g\xf3rnym\\r\\n- Wiadomo\u015Bci na chatcie s\u0105 limitowane do 20 na publicznym i 20 na prywatnym chatcie aby zapobiec crash\xf3w\\r\\n- Role nie s\u0105 ju\u017C ujawione dla duch\xf3w odrazu po \u015Bmierci\\r\\n- Pety s\u0105 poprawnie usuwane zale\u017Cnie od ustawie\u0144\\r\\n- Pow\xf3d \u015Bmierci Celebrity poprawnie si\u0119 wy\u015Bwietla"}]}}')}}]);